/** Black-box oracle (provided by the judge; do not modify). */
class Oracle {
    private final int a, b, limit;
    private int calls = 0;

    Oracle(int a, int b, int limit) {
        this.a = a;
        this.b = b;
        this.limit = limit;
    }

    /** Runs the given tests; returns true if the run FAILS (both conflicting tests are in subset). */
    public boolean run(int[] subset) {
        calls++;
        if (calls > limit) throw new IllegalStateException("run() called more than " + limit + " times");
        boolean hasA = false, hasB = false;
        for (int t : subset) {
            if (t == a) hasA = true;
            if (t == b) hasB = true;
        }
        return hasA && hasB;
    }
}

